ON CONFLICT DO NOTHING;

    -- Who holds the receivable: the seller (default), the platform after a debt sale,
    -- or a funder institution. The platform does not lend at origination.
CREATE TABLE IF NOT EXISTS installment_agreements (
    id                  BIGSERIAL PRIMARY KEY,
    reference           TEXT    NOT NULL UNIQUE,
    order_id            INTEGER NOT NULL REFERENCES orders(id) ON DELETE RESTRICT,
    user_id             INTEGER NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    plan_id             INTEGER NOT NULL REFERENCES installment_plans(id) ON DELETE RESTRICT,
    supplier_id         INTEGER REFERENCES suppliers(id) ON DELETE RESTRICT,
    months              INTEGER NOT NULL,
    fee_bps             INTEGER NOT NULL,
    down_payment_bps    INTEGER NOT NULL,
    principal_minor BIGINT NOT NULL CHECK (principal_minor > 0),
    down_payment_minor BIGINT NOT NULL CHECK (down_payment_minor >= 0),
    financed_minor BIGINT NOT NULL CHECK (financed_minor >= 0),
    fee_total_minor BIGINT NOT NULL CHECK (fee_total_minor >= 0),
    total_payable_minor BIGINT NOT NULL,
    creditor_kind       TEXT    NOT NULL DEFAULT 'seller'
                                CHECK (creditor_kind IN ('seller', 'platform', 'institution')),
    status              TEXT    NOT NULL DEFAULT 'active'
                                CHECK (status IN ('active', 'completed', 'defaulted', 'cancelled')),
    idempotency_key     TEXT    NOT NULL UNIQUE,
    created_by_user_id  INTEGER REFERENCES users(id) ON DELETE SET NULL,
    created_at          TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS"+00:00"')),
    updated_at          TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS"+00:00"')),
    CHECK (principal_minor = down_payment_minor + financed_minor),
    CHECK (total_payable_minor = principal_minor + fee_total_minor)
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_installment_agreements_order
    ON installment_agreements(order_id) WHERE status <> 'cancelled';

CREATE INDEX IF NOT EXISTS ix_installment_agreements_user ON installment_agreements(user_id, id);

CREATE OR REPLACE FUNCTION installment_agreements_terms_immutable_fn() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'installment agreement amounts are immutable' USING ERRCODE = '23000';
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER installment_agreements_terms_immutable
BEFORE UPDATE OF ORDER_ID, USER_ID, PLAN_ID, MONTHS, FEE_BPS, DOWN_PAYMENT_BPS, PRINCIPAL_MINOR, DOWN_PAYMENT_MINOR, FINANCED_MINOR, FEE_TOTAL_MINOR, TOTAL_PAYABLE_MINOR ON installment_agreements
FOR EACH ROW EXECUTE PROCEDURE installment_agreements_terms_immutable_fn();

CREATE OR REPLACE FUNCTION installment_agreements_no_delete_fn() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'installment_agreements cannot be deleted' USING ERRCODE = '23000';
    RETURN OLD;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER installment_agreements_no_delete
BEFORE DELETE ON installment_agreements
FOR EACH ROW EXECUTE PROCEDURE installment_agreements_no_delete_fn();

-- seq 0 = down payment (when > 0); 1..months = monthly installments.
CREATE TABLE IF NOT EXISTS installment_schedules (
    id                  BIGSERIAL PRIMARY KEY,
    agreement_id        INTEGER NOT NULL REFERENCES installment_agreements(id) ON DELETE RESTRICT,
    seq                 INTEGER NOT NULL CHECK (seq >= 0),
    due_at              TEXT    NOT NULL,
    principal_minor BIGINT NOT NULL CHECK (principal_minor >= 0),
    fee_minor BIGINT NOT NULL CHECK (fee_minor >= 0),
    amount_minor BIGINT NOT NULL CHECK (amount_minor > 0),
    status              TEXT    NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'paid', 'late')),
    is_late             INTEGER NOT NULL DEFAULT 0 CHECK (is_late IN (0, 1)),
    paid_at             TEXT,
    updated_at          TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS"+00:00"')),
    CHECK (amount_minor = principal_minor + fee_minor),
    UNIQUE (agreement_id, seq)
);

CREATE INDEX IF NOT EXISTS ix_installment_schedules_due ON installment_schedules(status, due_at);

CREATE OR REPLACE FUNCTION installment_schedules_amounts_immutable_fn() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'installment schedule amounts are immutable' USING ERRCODE = '23000';
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER installment_schedules_amounts_immutable
BEFORE UPDATE OF AGREEMENT_ID, SEQ, DUE_AT, PRINCIPAL_MINOR, FEE_MINOR, AMOUNT_MINOR ON installment_schedules
FOR EACH ROW EXECUTE PROCEDURE installment_schedules_amounts_immutable_fn();

CREATE OR REPLACE FUNCTION installment_schedules_no_delete_fn() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'installment_schedules cannot be deleted' USING ERRCODE = '23000';
    RETURN OLD;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER installment_schedules_no_delete
BEFORE DELETE ON installment_schedules
FOR EACH ROW EXECUTE PROCEDURE installment_schedules_no_delete_fn();

CREATE TABLE IF NOT EXISTS installment_payments (
    id                  BIGSERIAL PRIMARY KEY,
    reference           TEXT    NOT NULL UNIQUE,
    schedule_id         INTEGER NOT NULL REFERENCES installment_schedules(id) ON DELETE RESTRICT,
    agreement_id        INTEGER NOT NULL REFERENCES installment_agreements(id) ON DELETE RESTRICT,
    amount_minor BIGINT NOT NULL CHECK (amount_minor > 0),
    paid_at             TEXT    NOT NULL,
    external_reference  TEXT,
    idempotency_key     TEXT    NOT NULL UNIQUE,
