-- Seller sells the remaining receivable of an agreement to the platform at a discount.
CREATE TABLE IF NOT EXISTS debt_sales (
    id                      BIGSERIAL PRIMARY KEY,
    reference               TEXT    NOT NULL UNIQUE,
    agreement_id            INTEGER NOT NULL UNIQUE REFERENCES installment_agreements(id) ON DELETE RESTRICT,
    supplier_id             INTEGER NOT NULL REFERENCES suppliers(id) ON DELETE RESTRICT,
    remaining_minor BIGINT NOT NULL CHECK (remaining_minor > 0),
    discount_bps            INTEGER NOT NULL CHECK (discount_bps BETWEEN 0 AND 5000),
    discount_minor BIGINT NOT NULL CHECK (discount_minor >= 0),
    purchase_price_minor BIGINT NOT NULL CHECK (purchase_price_minor > 0),
    ledger_reference        TEXT    NOT NULL,
    idempotency_key         TEXT    NOT NULL UNIQUE,
    actor_user_id           INTEGER REFERENCES users(id) ON DELETE SET NULL,
    created_at              TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS"+00:00"')),
    CHECK (remaining_minor = purchase_price_minor + discount_minor)
);

CREATE OR REPLACE FUNCTION debt_sales_no_update_fn() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'debt_sales is append-only: UPDATE is forbidden' USING ERRCODE = '23000';
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER debt_sales_no_update
BEFORE UPDATE ON debt_sales
FOR EACH ROW EXECUTE PROCEDURE debt_sales_no_update_fn();

CREATE OR REPLACE FUNCTION debt_sales_no_delete_fn() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'debt_sales is append-only: DELETE is forbidden' USING ERRCODE = '23000';
    RETURN OLD;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER debt_sales_no_delete
BEFORE DELETE ON debt_sales
FOR EACH ROW EXECUTE PROCEDURE debt_sales_no_delete_fn();

-- ================================================================ seller advances
-- grant (+) creates the obligation; recovery (+) nets it out at settlement.
-- outstanding(supplier) = SUM(grant) - SUM(recovery).
    -- grant only: the eligible delivered-unsettled net and the rate it was capped at.
CREATE TABLE IF NOT EXISTS seller_advance_entries (
    id                      BIGSERIAL PRIMARY KEY,
    reference               TEXT    NOT NULL UNIQUE,
    supplier_id             INTEGER NOT NULL REFERENCES suppliers(id) ON DELETE RESTRICT,
    entry_type              TEXT    NOT NULL CHECK (entry_type IN ('grant', 'recovery')),
    amount_minor BIGINT NOT NULL CHECK (amount_minor > 0),
    basis_net_minor BIGINT,
    rate_bps                INTEGER CHECK (rate_bps IS NULL OR rate_bps BETWEEN 0 AND 9000),
    settlement_reference    TEXT,
    ledger_reference        TEXT    NOT NULL,
    idempotency_key         TEXT    NOT NULL UNIQUE,
    actor_user_id           INTEGER REFERENCES users(id) ON DELETE SET NULL,
    created_at              TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS"+00:00"'))
);

CREATE INDEX IF NOT EXISTS ix_seller_advance_supplier ON seller_advance_entries(supplier_id, id);

CREATE OR REPLACE FUNCTION seller_advance_entries_no_update_fn() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'seller_advance_entries is append-only: UPDATE is forbidden' USING ERRCODE = '23000';
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

