    RETURN OLD;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER seller_advance_entries_no_delete
BEFORE DELETE ON seller_advance_entries
FOR EACH ROW EXECUTE PROCEDURE seller_advance_entries_no_delete_fn();

-- ================================================================ group platform
-- One group-wide identity per user across 60Online, KarenSeir, Giftasan, Shadshahr, Padvira.
CREATE TABLE IF NOT EXISTS group_accounts (
    id                      BIGSERIAL PRIMARY KEY,
    user_id                 INTEGER NOT NULL UNIQUE REFERENCES users(id) ON DELETE RESTRICT,
    group_uid               TEXT    NOT NULL UNIQUE,
    linked_businesses_json  TEXT    NOT NULL DEFAULT '["60online"]',
    provider                TEXT    NOT NULL DEFAULT 'local',
    status                  TEXT    NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended')),
    created_at              TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS"+00:00"')),
    updated_at              TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS"+00:00"'))
);

